"""Emit native POD command capture. No Encore graphs or borrowed stack arrays escape."""
from pathlib import Path
import re
# Parameter type, name, optional element count/type for copied spans.
commands=[
('vkCmdUpdateBuffer',[('void *','cmd'),('void *','buffer'),('uint64_t','offset'),('uint64_t','size'),('const void *','values','size','unsigned char')]),
('vkCmdBindPipeline',[('void *','cmd'),('uint32_t','point'),('void *','pipeline')]),
('vkCmdDispatch',[('void *','cmd'),('uint32_t','x'),('uint32_t','y'),('uint32_t','z')]),
('vkCmdDispatchIndirect',[('void *','cmd'),('void *','buffer'),('uint64_t','offset')]),
('vkCmdFillBuffer',[('void *','cmd'),('void *','buffer'),('uint64_t','offset'),('uint64_t','size'),('uint32_t','value')]),
('vkCmdEndRenderPass',[('void *','cmd')]),
('vkCmdDraw',[('void *','cmd')]+[('uint32_t',x) for x in ['vertices','instances','first','first_instance']]),
('vkCmdDrawIndexed',[('void *','cmd'),('uint32_t','indices'),('uint32_t','instances'),('uint32_t','first'),('int32_t','offset'),('uint32_t','first_instance')]),
('vkCmdBindIndexBuffer',[('void *','cmd'),('void *','buffer'),('uint64_t','offset'),('uint32_t','type')]),
('vkCmdDrawIndexedIndirectCount',[('void *','cmd'),('void *','buffer'),('uint64_t','offset'),('void *','counts'),('uint64_t','count_offset'),('uint32_t','maximum'),('uint32_t','stride')]),
('vkCmdDrawMeshTasksEXT',[('void *','cmd'),('uint32_t','x'),('uint32_t','y'),('uint32_t','z')]),
('vkCmdDrawMeshTasksIndirectEXT',[('void *','cmd'),('void *','buffer'),('uint64_t','offset'),('uint32_t','count'),('uint32_t','stride')]),
('vkCmdPushConstants',[('void *','cmd'),('void *','layout'),('uint32_t','stages'),('uint32_t','offset'),('uint32_t','size'),('const void *','values','size','unsigned char')]),
('vkCmdSetViewport',[('void *','cmd'),('uint32_t','first'),('uint32_t','count'),('const VkViewport *','values','count','VkViewport')]),
('vkCmdSetScissor',[('void *','cmd'),('uint32_t','first'),('uint32_t','count'),('const VkRect2D *','values','count','VkRect2D')]),
('vkCmdBindVertexBuffers',[('void *','cmd'),('uint32_t','first'),('uint32_t','count'),('void *const *','buffers','count','void *'),('const uint64_t *','offsets','count','uint64_t')]),
('vkCmdBindDescriptorSets',[('void *','cmd'),('uint32_t','point'),('void *','layout'),('uint32_t','first'),('uint32_t','count'),('void *const *','sets','count','void *'),('uint32_t','dynamic_count'),('const uint32_t *','offsets','dynamic_count','uint32_t')]),
('vkCmdCopyBuffer',[('void *','cmd'),('void *','source'),('void *','target'),('uint32_t','count'),('const VkBufferCopy *','regions','count','VkBufferCopy')]),
('vkCmdCopyBufferToImage',[('void *','cmd'),('void *','source'),('void *','target'),('uint32_t','layout'),('uint32_t','count'),('const VkBufferImageCopy *','regions','count','VkBufferImageCopy')]),
('vkCmdCopyImageToBuffer',[('void *','cmd'),('void *','source'),('uint32_t','layout'),('void *','target'),('uint32_t','count'),('const VkBufferImageCopy *','regions','count','VkBufferImageCopy')]),
('vkCmdClearColorImage',[('void *','cmd'),('void *','image'),('uint32_t','layout'),('const VkClearColorValue *','color','1','VkClearColorValue'),('uint32_t','count'),('const VkImageSubresourceRange *','ranges','count','VkImageSubresourceRange')]),
('vkCmdPipelineBarrier',[('void *','cmd'),('uint32_t','source'),('uint32_t','target'),('uint32_t','flags'),('uint32_t','memory_count'),('const void *','memory','memory_count','VkMemoryBarrier'),('uint32_t','buffer_count'),('const void *','buffers','buffer_count','EncoreParallelBufferBarrier'),('uint32_t','image_count'),('const VkImageMemoryBarrier *','images','image_count','VkImageMemoryBarrier')]),
('vkCmdResetQueryPool',[('void *','cmd'),('uint64_t','pool'),('uint32_t','first'),('uint32_t','count')]),
('vkCmdWriteTimestamp',[('void *','cmd'),('uint32_t','stage'),('uint64_t','pool'),('uint32_t','query')]),
]
out=['/* Generated by tools/generate_parallel_commands.py. */',
'''typedef VkBufferMemoryBarrier EncoreParallelBufferBarrier;''']
for name,params in commands:
 tag=name[2:]; fields='\n'.join(f'    {t} {n};' for t,n,*_ in params)
 types=','.join(t for t,n,*_ in params); args=','.join(n for t,n,*_ in params)
 out += [f'typedef struct {{\n    void (*fn)({types});\n{fields}\n}} EncoreCapture{tag};']
 out += [f'static void encore_replay_{tag}(unsigned char *bytes) {{',f'    EncoreCapture{tag} a=*(EncoreCapture{tag} *)bytes;']
 spans=[p for p in params if len(p)==4]
 if spans:out += [f'    unsigned char *tail=bytes+encore_parallel_align(sizeof(a));']
 for t,n,count,elem in spans:
  expr=re.sub(r'\b([A-Za-z_]\w*)\b',lambda m:'a.'+m[1] if m[1] in [p[1] for p in params] else m[1],count)
  out += [f'    a.{n}=({t})tail;tail+=encore_parallel_align((size_t)({expr})*sizeof({elem}));']
 out += [f'    a.fn({",".join("a."+p[1] for p in params)});','}']
 out += [f'static void encore_capture_{tag}({",".join(t+" "+n for t,n,*_ in params)}) {{',f'    EncoreParallelCommand *c=encore_parallel_command(cmd);',f'    if(!c)return;',f'    size_t total=encore_parallel_align(sizeof(EncoreCapture{tag}));']
 for t,n,count,elem in spans:out += [f'    total+=encore_parallel_align((size_t)({count})*sizeof({elem}));']
 out += [f'    EncoreCapture{tag} *a=encore_parallel_append(c,total,encore_replay_{tag});', '    if(!a)return;',f'    a->fn=(void (*)({types}))c->owner->proc(c->owner->device,"{name}");']
 for t,n,*_ in params:out += [f'    a->{n}={n};']
 if spans:out += ['    unsigned char *tail=(unsigned char *)a+encore_parallel_align(sizeof(*a));']
 for t,n,count,elem in spans:out += [f'    if(({count}) && {n})memcpy(tail,{n},(size_t)({count})*sizeof({elem}));tail+=encore_parallel_align((size_t)({count})*sizeof({elem}));']
 out += ['}']
out += ['static VkVoidFunction encore_parallel_command_proc(const char *name) {']
for name,_ in commands:out += [f'    if(!strcmp(name,"{name}"))return (VkVoidFunction)encore_capture_{name[2:]};']
out += ['    if(!strcmp(name,"vkCmdDrawIndexedIndirectCountKHR"))return (VkVoidFunction)encore_capture_CmdDrawIndexedIndirectCount;','    return NULL;','}']
Path(__file__).resolve().parents[1].joinpath('parallel_commands.inc').write_text('\n'.join(out)+'\n')
